class Car {
  constructor(x, y) {
    this.x = x;
    this.y = y;
    this.vx = 4;
    this.vy = 0;
    this.width = 40;
    this.height = 20;
    this.alive = true;
    this.frontBroken = false;
    this.parts = [
      { x: this.x, y: this.y, w: 40, h: 20, vx: 4, vy: 0 },
      // broken parts
    ];
  }

  update() {
    if (!this.alive) return;
    this.x += this.vx;
    this.y += this.vy;
    this.vy += 0.5; // gravity

    // Ground collision
    if (this.y + this.height > canvas.height - 50) {
      this.y = canvas.height - 50 - this.height;
      this.vy *= 0.6;
      if (Math.abs(this.vy) < 0.5) this.vy = 0;
    }

    // Wall collision
    const wallX = canvas.width / 2 - 20; // wall position
    if (this.x + this.width > wallX && !this.frontBroken) {
      this.hitWall();
    }
  }

  hitWall() {
    this.alive = false;
    // Damage: crumple front
    this.frontBroken = true;
    // Sparks
    createSparks(this.x, this.y);
  }
}
