```javascript
const canvas = document.getElementById('c');
const ctx = canvas.getContext('2d');

let W, H;
function resize() {
  W = canvas.width = window.innerWidth;
  H = canvas.height = window.innerHeight;
}
window.addEventListener('resize', resize);
resize();

// Game state
let car, bricks, particles, gameOver, score;

// Car
function createCar() {
  return {
    x: 50,
    y: H - 450,
    w: 50,
    h: 25,
    vx: 3.5,
    vy: 0,
    alive: true,
    damage: false,
    crumple: 0
  };
}

// Bricks
const BRICK_W = 30;
const BRICK_H = 20;
const ROWS = 6;
const COLS = 10;

function createBricks() {
  bricks = [];
  for (let r = 0; r < ROWS; r++) {
    for (let c = 0; c < COLS; c++) {
      bricks.push({
        x: 100 + c * (BRICK_W + 5),
        y: 80 + r * (BRICK_H + 5),
        w: BRICK_W,
        h: BRICK_H,
        vx: 0,
        vy: 0,
        alive: true
      });
    }
  }
}

// Particles
function createParticles(x, y) {
  for (let i = 0; i < 8; i++) {
    particles.push({
      x: x + Math.random() * BRICK_W,
      y: y,
      vx: (Math.random() - 0.5) * 4,
      vy: -Math.random() * 3 - 1,
      life: 30,
      size: Math.random() * 4 + 2,
      color: Math.random() > 0.5 ? '#ff6600' : '#ffff66'
    });
  }
}

// Sparks
function createSparks(x, y) {
  for (let i = 0; i < 15; i++) {
    particles.push({
      x: x,
      y: y,
      vx: (Math.random() - 0.5) * 6,
      vy: Math.random() * 4 + 2,
      life: 20,
      size: Math.random() * 3 + 1,
      color: '#ffaa00'
    });
  }
}

// Update
function update() {
  // Car update
  if (car && car.alive) {
    car.x += car.vx;
    car.y += car.vy;
    car.vy += GRAVITY;

    // Ground collision
    const groundY = H - 50;
    if (car.y + car.h > groundY) {
      car.y = groundY - car.h;
      car.vy *= 0.7;
      if (Math.abs(car.vy) < 0.3) car.vy = 0;
    }

    // Wall collision
    const wallX = W * 0.6 - 30;
    if (car.x + car.w > wallX && !car.crumple) {
      car.crumple++;
      car.damage = true;
      createSparks(car.x + car.w/2, car.y);
      // Knock bricks
      knockBricks();
    }
  }

  // Brick updates
  for (let b of bricks) {
    if (!b.alive) continue;
    b.x += b.vx;
    b.y += b.vy;
    b.vy += GRAVITY;

    // Ground collision
    const groundY = H - 50;
    if (b.y + b.h > groundY) {
      b.y = groundY - b.h;
      b.vy *= 0.6;
      if (Math.abs(b.vy) < 0.3) b.vy = 0;
    }

    // Wall collision (bricks can't go past wall)
    const wallX = W * 0.6 - 30;
    if (b.x + b.w > wallX) {
      b.x = wallX - b.w;
      b.vx *= -0.5;
    }
  }

  // Particles
  for (let i = particles.length - 1; i >= 0; i--) {
    const p = particles[i];
    p.x += p.vx;
    p.y += p.vy;
    p.vy += 0.1;
    p.life--;
    if (p.life <= 0) particles.splice(i, 1);
  }

  // Update score
  document.getElementById('count').textContent = score;
}

// Knock bricks on impact
function knockBricks() {
  let knocked = 0;
  for (let b of bricks) {
    if (!b.alive) continue;
    // Check distance to car
    const dx = b.x + b.w/2 - car.x;
    const dy = b.y + b.h/2 - car.y;
    const dist = Math.sqrt(dx*dx + dy*dy);
    if (dist < 80) {
      b.alive = false;
      b.vx = -Math.random() * 4;
      b.vy = -Math.random() * 3 - 1;
      knocked++;
      score++;
    }
  }
  // Also break off car front
  if (car.crumple < 2) {
    createParticles(car.x + car.w/2, car.y);
  }
}
