      ctx.fillStyle = car.damage ? '#8b0000' : '#d35400';
      ctx.fillRect(car.x, car.y, car.w, car.h);

      // Wheels
      ctx.fillStyle = '#333';
      ctx.fillRect(car.x + 10, car.y + car.h - 6, 8, 6);
      ctx.fillRect(car.x + car.w - 18, car.y + car.h - 6, 8, 6);

      // Damage: broken front piece
      if (car.damage && car.crumple > 0) {
        ctx.fillStyle = '#ff6666';
        ctx.fillRect(car.x + car.w * 0.25, car.y + 5, car.w * 0.35, 8);
      }
    }

    function drawBricks() {
      for (let b of bricks) {
        if (!b.alive) continue;
        ctx.fillStyle = '#c0392b';
        ctx.fillRect(b.x, b.y, b.w, b.h);
        ctx.strokeStyle = '#e74c3c';
        ctx.strokeRect(b.x, b.y, b.w, b.h);
      }
    }

    function drawParticles() {
      for (let p of particles) {
        ctx.globalAlpha = Math.max(0, p.life / 20);
        ctx.fillStyle = p.color;
        ctx.beginPath();
        ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
        ctx.fill();
      }
      ctx.globalAlpha = 1;
    }

    function draw() {
      // Background
      ctx.fillStyle = '#1a1a2e';
      ctx.fillRect(0, 0, W, H);

      // Road
      ctx.fillStyle = '#2c3e50';
      ctx.fillRect(0, GROUND_Y, W, H - GROUND_Y);

      // Road markings
      ctx.fillStyle = '#4a6572';
      for (let x = 0; x < W; x += 60) {
        ctx.fillRect(x, GROUND_Y + 8, 40, 3);
      }

      drawBricks();
      drawCar();
      drawParticles();
    }

    function loop() {
      updateCar();
      updateBricks();
      updateParticles();
      draw();
      requestAnimationFrame(loop);
    }

    function init() {
      car = createCar();
      createBricks();
      particles = [];
      score = 0;
      stopped = false;
      document.getElementById('count').textContent = score;
      document.getElementById('replayBtn').style.display = 'block';
    }

    init();

    document.getElementById('replayBtn').addEventListener('click', () => {
      init();
    });

    loop();
  </script>
</body>
